<script setup lang="ts">const shop=useShop();const route=useRoute();const order=computed(()=>shop.orders.find(o=>o.id===route.query.order)||shop.orders[0]);</script><template><div class="mx-auto w-full max-w-7xl px-4 sm:px-6 lg:px-8 py-16"><div v-if="order" class="mx-auto max-w-2xl rounded-3xl border border-gray-100 p-8 text-center shadow-sm sm:p-12"><div class="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-blue-50 text-3xl text-brand">✓</div><p class="mt-6 text-xs font-bold uppercase tracking-[.2em] text-brand">Demo order placed</p><h1 class="mt-2 text-4xl font-semibold tracking-tight">You're all set<span class="text-brand">.</span></h1><p class="mt-4 text-sm leading-6 text-gray-500">Thanks, {{ order.customer.name }}. Your demo order has been saved in this browser. No payment was taken.</p><div class="mt-8 rounded-2xl bg-mist p-5 text-left"><div class="flex justify-between gap-3"><span class="text-xs text-gray-500">Order reference</span><strong class="text-sm">{{ order.id }}</strong></div><div class="mt-3 flex justify-between gap-3"><span class="text-xs text-gray-500">Order date</span><span class="text-xs">{{ new Date(order.createdAt).toLocaleString() }}</span></div><div class="mt-3 flex justify-between gap-3"><span class="text-xs text-gray-500">Demo status</span><span class="text-xs font-semibold">{{ order.status }}</span></div><div class="mt-4 border-t border-gray-200 pt-4"><div v-for="item in order.items" :key="item.key" class="flex justify-between py-1 text-xs"><span>{{ item.productName }} × {{ item.quantity }}</span><span>${{ (item.unitPrice*item.quantity).toFixed(2) }}</span></div><div class="mt-3 flex justify-between border-t border-gray-200 pt-3 font-bold"><span>Total</span><span>${{ order.total.toFixed(2) }}</span></div></div></div><div class="mt-7 flex flex-wrap justify-center gap-3"><NuxtLink to="/account/orders" class="rounded-full bg-ink px-6 py-3 text-xs font-bold uppercase tracking-wider text-white">View order history</NuxtLink><NuxtLink to="/shop" class="rounded-full border border-gray-200 px-6 py-3 text-xs font-bold uppercase tracking-wider">Keep exploring</NuxtLink></div></div><EmptyState v-else title="No demo order found" description="Place a demo order first, then you'll see the confirmation here." to="/shop" action-label="Start shopping"/></div></template>
